import{_ as s,C as t,o as n,c as o,E as a,a2 as i}from"./chunks/framework.Cc8dJFaW.js";const f=JSON.parse('{"title":"确认请求出现了，风险分析器究竟看见了什么","description":"","frontmatter":{"title":"确认请求出现了，风险分析器究竟看见了什么","article_type":"technical-analysis","edition":"research-center","research_question":"确认请求能说明动作被审查到什么程度，而不能说明哪些环境危险已被识别？","summary":"未知风险可以触发确认，分析异常也可以被标为高风险；这两种行为都不能说明环境危险已经被识别。结合固定源码、内部隔离探针和独立环境危险研究，本文给出一份检查审查证据是否抵达决策点的方法。","sources":"https://docs.openhands.dev/sdk/guides/security; https://arxiv.org/html/2611.26553v1","date":"2026-11-23","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261123-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-23-sig-20261123-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-11-23-sig-20261123-003.md","filePath":"zh/digital-employee/2026-11-23-sig-20261123-003.md","lastUpdated":1795436571000}'),l={name:"zh/digital-employee/2026-11-23-sig-20261123-003.md"};function h(c,e,p,b,u,g){const r=t("ArticleCover"),d=t("ArticleTableScroll");return n(),o("div",null,[a(r,{image:"/assets/covers/daily-2026-11-23-sig-20261123-003-cover.png",kicker:"研究成果",title:"确认请求出现了，风险分析器究竟看见了什么",summary:"未知风险可以触发确认，分析异常也可以被标为高风险；这两种行为都不能说明环境危险已经被识别。结合固定源码、内部隔离探针和独立环境危险研究，本文给出一份检查审查证据是否抵达决策点的方法。",version:"2026-11-23",languageHref:"/en/digital-employee/2026-11-23-sig-20261123-003",languageLabel:"English"}),a(d,{language:"zh"}),e[0]||(e[0]=i('<h1 id="确认请求出现了-风险分析器究竟看见了什么" tabindex="-1">确认请求出现了，风险分析器究竟看见了什么 <a class="header-anchor" href="#确认请求出现了-风险分析器究竟看见了什么" aria-label="Permalink to &quot;确认请求出现了，风险分析器究竟看见了什么&quot;">​</a></h1><p>在本次内部隔离探针中，同样一个“风险未知”的输入，只改一个配置开关，就能从“需要确认”变成“不需要确认”。弹出的询问因此首先说明策略作出了什么决定，不能说明分析器识别了哪些危险。负责智能体动作审查的工程师，需要沿着目标环境、风险依据和确认决定逐项追踪，而不能从按钮反推观察已经完整。</p><h2 id="询问发生在观察之后" tabindex="-1">询问发生在观察之后 <a class="header-anchor" href="#询问发生在观察之后" aria-label="Permalink to &quot;询问发生在观察之后&quot;">​</a></h2><p>OpenHands（软件开发智能体项目）的安全指南把两个责任分开：分析器给动作评估风险，确认策略决定是否询问用户。总是询问、从不询问和按风险询问，是不同策略；只配置分析器并不会自动启用确认。<a href="https://docs.openhands.dev/sdk/guides/security" target="_blank" rel="noreferrer">官方安全指南</a></p><p>固定源码中的按风险确认策略，默认采用高风险阈值，并默认对未知风险请求确认；未知值不能被用作阈值。对于已知风险，它把比较交给风险比较方法。这是一个由风险评级映射到询问决定的接口，并不负责证明评级所依据的信息完整。<a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">固定确认策略源码</a></p><p>一个明确标为示意的例子是：动作文字只写“清理临时文件”，解析后的目录却可能指向受保护资源。这里没有声称发现了该项目的漏洞。这个例子只说明审查者需要追问：实际目标、当前环境和潜在后果有没有进入风险分析？即使询问环节工作正常，这些信息缺失仍可能让人批准一件自己没有看清的事。</p><h2 id="风险未知与分析失败是两种情况" tabindex="-1">风险未知与分析失败是两种情况 <a class="header-anchor" href="#风险未知与分析失败是两种情况" aria-label="Permalink to &quot;风险未知与分析失败是两种情况&quot;">​</a></h2><p>同日分析阶段执行了一个源码派生的内部隔离探针。它从固定版本提取确认方法和基础批处理辅助方法，保留函数体，移除装饰器，并用明确的替身对象提供依赖。以下是已保存的实际输出，不是本篇重新运行的集成测试。</p><table tabindex="0"><thead><tr><th>输入与对照</th><th>观察到的输出</th><th>能说明的范围</th></tr></thead><tbody><tr><td>风险未知，未知风险确认开关开启</td><td>请求确认</td><td>该方法的默认分支</td></tr><tr><td>同一未知输入，只关闭该开关</td><td>不请求确认</td><td>配置可以改变这个分支</td></tr><tr><td>分析器正常返回低风险</td><td>低风险，无详情</td><td>基础批处理的正常路径</td></tr><tr><td>分析器抛出受控异常</td><td>高风险，详情保留错误</td><td>基础批处理的异常降落路径</td></tr></tbody></table><p>因此，“没有得到可靠分类”至少要继续区分信息未知和分析过程报错。后者在这个辅助方法中被转为高风险，不意味着异常原因被解决，也不等于最终一定阻断执行；最终行为还依赖确认策略和实际调用路径。<a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/analyzer.py" target="_blank" rel="noreferrer">固定分析器源码</a></p><p>内部实验没有运行完整开发包、风险比较器、配置校验、人工界面或对话循环，也没有测量环境危险识别能力。它支持的是局部决策行为。把这张表称为安全有效性测试，会把函数输出扩大成尚未观察的实际效果。<a href="/joinwell52/assets/evidence/2026-11-23-sig-20261123-003/experiment-evidence.json">内部实验输入、输出与边界</a></p><h2 id="环境证据改变了审查问题" tabindex="-1">环境证据改变了审查问题 <a class="header-anchor" href="#环境证据改变了审查问题" aria-label="Permalink to &quot;环境证据改变了审查问题&quot;">​</a></h2><p>来自得克萨斯农工大学的独立研究团队，在 ROGUE-AI（环境危险重建研究）中比较事故环境和经过最小改动的对照环境，并依据环境状态检查伤害，而不只相信智能体最后的文字。作者报告，72 起涉及现实伤害的收集案例中，62 起不含攻击者。这是入选案例的分类，不是所有智能体事故的比例。<a href="https://arxiv.org/html/2611.26553v1" target="_blank" rel="noreferrer">论文第一版，第 3—6 节</a></p><p>这项研究的重要补充是：普通任务行为也可能遇到环境危险，审查不能只找恶意指令。作者在每个模型选取的 7—11 个高伤害重建案例中，重复提供危险及其后果的提醒，报告其伤害下降优于等长中性提醒；不同模型仍有明显残余伤害。这些结果来自选定的合成条件，不能直接换算为实际部署的风险下降，也不能与全套任务的伤害百分比直接相减。</p><p>重建本身也有不确定性。论文报告七个重建未满足环境状态差异条件，部分邮件服务器案例测到了组件行为而非模型选择；盲重建的 11 个事故结果中有五个不一致。确认是在模拟条件下处理的，没有自适应确认的比较。因此，这项研究提出了应检查的信息，却没有测试上述开发包的配置，更没有独立复现它的安全效果。</p><h2 id="检查抵达决策点的证据" tabindex="-1">检查抵达决策点的证据 <a class="header-anchor" href="#检查抵达决策点的证据" aria-label="Permalink to &quot;检查抵达决策点的证据&quot;">​</a></h2><p>我们的工程解释是：审查记录应让人分清“看到了什么”“怎样评级”“怎样决定”和“实际发生了什么”。下面是一份建议检查表，不是现有项目承诺实现的接口，也不要求所有系统采取同一种存储结构。</p><table tabindex="0"><thead><tr><th>交接位置</th><th>负责检查的人或组件</th><th>应保留的依据</th><th>不能据此放行的情况</th></tr></thead><tbody><tr><td>动作解析到环境观察</td><td>调用方与环境适配组件</td><td>解析后的目标、观察时点、可达权限和受保护资源状态</td><td>目标或环境无法确认</td></tr><tr><td>环境观察到风险分析</td><td>分析器维护者</td><td>识别到的危险、预期后果、评级依据及缺失信息</td><td>只剩评级，依据不可追溯</td></tr><tr><td>风险分析到人工决定</td><td>策略与审批界面维护者</td><td>实际策略配置、展示的动作及环境信息、决定所针对的对象</td><td>人看到的对象和待执行对象无法对应</td></tr><tr><td>决定到效果检查</td><td>执行方与业务验收者</td><td>实际动作及其结果状态</td><td>只有批准记录，没有效果证据</td></tr></tbody></table><p>例如检查一次“清理临时文件”的请求，不应先写一个貌似完整的高风险说明。应先追踪目录解析的结果和观察来源，再检查这些依据是否进入分析器、是否展示给审批者；缺失项保持“未观察”。是否阻断以及怎样补充观察，应由部署规则明确决定，不能由一个通用示例代替风险政策。</p><p>这张表的价值在于定位信息在哪次交接丢失：分析器收到的信息不足，与分析器在充分信息下判断错误，是不同问题；人没有看到危险，与人看到后仍决定继续，也需要不同证据。确认次数本身无法替代这些区分。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文把公开实现事实、来源报告和内部实验分开：源码说明固定版本实际写了什么；论文数字是作者报告；内部隔离探针只检查两个局部方法。建议检查表是我们的解释，尚未经过部署效果验证。</p><ul><li><a href="https://docs.openhands.dev/sdk/guides/security" target="_blank" rel="noreferrer">项目官方安全指南</a>：2026-11-23 读取快照，说明分析与确认责任及已知边界；文档明确把直接工具执行排除在所述对话循环保护之外，并指出分类不是沙箱或硬性拒绝机制。本文没有执行绕过攻击。</li><li><a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">确认策略实现</a>与<a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/analyzer.py" target="_blank" rel="noreferrer">分析器实现</a>：均固定于链接所示提交；文档与代码属于同一个维护主体，不算两个独立来源。</li><li><a href="https://arxiv.org/html/2611.26553v1" target="_blank" rel="noreferrer">环境危险研究第一版</a>：孟晓·王、马赫布卜·阿拉姆、卡利安·纳卡与尼泰什·萨克塞纳的预印本，为独立研究主体的作者报告，不是针对该实现的独立验证。本文没有取得操作性事故档案或执行事故重建。</li></ul><h2 id="这次比较还不能说明什么" tabindex="-1">这次比较还不能说明什么 <a class="header-anchor" href="#这次比较还不能说明什么" aria-label="Permalink to &quot;这次比较还不能说明什么&quot;">​</a></h2><p>保守地对所有动作询问，也不能自动弥补缺失的环境信息；但若一个固定、隔离且无危险副作用的任务，所需环境事实已经完整，额外的通用危险清单也可能没有收益。两种情况都不能仅靠询问是否出现来判断。</p><p>本篇没有测量任何部署的危险检出率、误报率或伤害下降。下一步可在受保护的测试环境中固定动作，分别改变可见的目标与后果信息，记录分析依据、人工可见内容和实际状态；再检验新增信息是否改善了决定。还需单独检查等待期间环境变化后，原决定是否仍对应同一动作。完成这些验证之前，应保留“信息未观察”与“尚未验证效果”这两个不同缺口。</p>',26))])}const _=s(l,[["render",h]]);export{f as __pageData,_ as default};
